with cleaned as (select id, customer_id, plan, start_date, end_date, monthly_fee, status, coalesce(monthly_fee, 0) as monthly_fee_filled, case when monthly_fee >= 212 then 'High' when monthly_fee >= 63 then 'Medium' else 'Low' end as monthly_fee_tier from subscriptions where start_date > date '2023-04-18') select id, status, kpi, metric_value from (select id, status, monthly_fee, monthly_fee_filled from cleaned) src unpivot include nulls (metric_value for kpi in (monthly_fee, monthly_fee_filled))
